-- p_jugadas: [{"pregunta": "esc-001", "respuesta": 2, "ms": 4200}, …]. Devuelve aciertos, puntos y el tiempo total.
-- Una respuesta en menos de 300 ms no es de una persona: cuenta como 300 ms (no se premia el reflejo de un programa).
create or replace function public.corregir_partida(p_jugadas jsonb, p_segundos int, p_max int)
returns table (aciertos int, puntos int, ms int)
language plpgsql security definer set search_path = public stable as $$
declare j jsonb; c smallint; t int; total_ms int := p_segundos * 1000; a int := 0; p int := 0; m int := 0; n int := 0; vistas text[] := '{}';
begin
  if jsonb_typeof(p_jugadas) <> 'array' then raise exception 'jugadas_invalidas'; end if;
  for j in select * from jsonb_array_elements(p_jugadas) loop
    n := n + 1;
    exit when n > p_max;
    if (j->>'pregunta') = any (vistas) then continue; end if;   -- la misma pregunta dos veces no suma dos veces
    vistas := array_append(vistas, j->>'pregunta');
    t := least(total_ms, greatest(300, coalesce((j->>'ms')::int, total_ms)));
    m := m + t;
    select correcta into c from public.preguntas_clave where id = j->>'pregunta';
    if found and (j->>'respuesta') is not null and (j->>'respuesta')::smallint = c then
      a := a + 1;
      p := p + round(1000 * (1 - (t::numeric / total_ms) / 2))::int;
    end if;
  end loop;
  return query select a, p, m;
end $$;
revoke execute on function public.corregir_partida(jsonb, int, int) from public;

